enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status = INTEGRITY_PASS;
    void *digest = NULL;
    size_t digest_len = 0;
    int rc;

    if (iint->flags & INTEGRITY_FLAGS_BROKEN)
        return INTEGRITY_NOLIB;

    rc = get_xattr_digest(dentry, xattr_name, &digest, &digest_len);
    if (rc < 0) {
        if (rc == -ENODATA)
            status = INTEGRITY_NOLIB;
        else
            status = INTEGRITY_FAIL;
        goto out;
    }

    if (digest_len != xattr_value_len) {
        status = INTEGRITY_FAIL;
        goto out_free;
    }

    if (memcmp(digest, xattr_value, digest_len) != 0)
        status = INTEGRITY_FAIL;

out_free:
    kfree(digest);
out:
    if (status != INTEGRITY_PASS)
        iint->flags |= INTEGRITY_FLAGS_BROKEN;
    return status;
}

enum integrity_status verify_hmac_for_xattr(struct dentry *dentry,
                                            const char *xattr_name,
                                            char *xattr_value,
                                            size_t xattr_value_len,
                                            struct integrity_iint_cache *iint)
{
    enum integrity_status status = INTEGRITY_PASS;
    int result;
    char *digest = NULL;
    size_t digest_len = 0;

    if (!iint || iint->flags & INTEGRITY_PASS)
        return INTEGRITY_PASS;

    result = get_xattr_data_and_type(dentry, xattr_name, &digest, &digest_len);
    if (result < 0) {
        status = (result == -ENODATA) ? INTEGRITY_NOLABEL : INTEGRITY_FAIL;
        goto out;
    }

    result = verify_digest(xattr_value, xattr_value_len, digest, digest_len);
    if (result != 0)
        status = INTEGRITY_FAIL;

    kfree(digest);

out:
    iint->flags |= (status == INTEGRITY_PASS) ? INTEGRITY_PASS : INTEGRITY_FAIL;
    return status;
}

enum integrity_status verify_hmac_for_xattr(struct dentry *dentry,
                                            const char *xattr_name,
                                            char *xattr_value,
                                            size_t xattr_value_len,
                                            struct integrity_iint_cache *iint)
{
    enum integrity_status status = INTEGRITY_PASS;
    int error;
    void *digest = NULL;
    size_t digest_len = 0;
    void *calculated_digest = NULL;
    size_t calculated_len = 0;

    if (iint->flags & INTEGRITY_HMAC_DIGEST) {
        digest = iint->hmac;
        digest_len = iint->hmac_len;
    } else if (iint->flags & INTEGRITY_HASH_DIGEST) {
        digest = iint->hash;
        digest_len = iint->hash_len;
    } else {
        return INTEGRITY_NA;
    }

    error = calculate_hmac_or_hash(dentry, xattr_name, xattr_value, xattr_value_len,
                                   &calculated_digest, &calculated_len, iint);
    if (error < 0) {
        status = INTEGRITY_FAIL;
        goto out;
    }

    if (calculated_len != digest_len || memcmp(calculated_digest, digest, digest_len) != 0) {
        status = INTEGRITY_FAIL;
    }

out:
    kfree(calculated_digest);
    return status;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint)
{
    enum integrity_status status;
    void *digest;
    size_t digest_len;
    int result;

    if (!iint || iint->flags & INTEGRITY_FLAGS_NO_XATTR)
        return INTEGRITY_STATUS_NO_ATTRIBUTE;

    digest = kmalloc(xattr_value_len, GFP_KERNEL);
    if (!digest)
        return INTEGRITY_STATUS_FAILURE;

    result = getxattr(dentry->d_inode, xattr_name, digest, xattr_value_len);
    if (result < 0) {
        kfree(digest);
        return INTEGRITY_STATUS_FAILURE;
    }

    digest_len = (size_t)result;

    if (is_hmac(dentry->d_inode, xattr_name)) {
        status = verify_hmac(dentry, xattr_name, digest, digest_len, xattr_value, xattr_value_len);
    } else {
        status = verify_hash(digest, digest_len, xattr_value, xattr_value_len);
    }

    kfree(digest);

    if (status != INTEGRITY_STATUS_PASS)
        iint->flags |= INTEGRITY_FLAGS_FAILURE;

    return status;
}

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name,
                                        char *xattr_value, size_t xattr_value_len,
                                        struct integrity_iint_cache *iint) {
    enum integrity_status status = INTEGRITY_PASS;

    if (!iint)
        return INTEGRITY_NO_SIGNATURE;

    if (iint->flags & INTEGRITY_FLAGS_HMAC) {
        void *digest = NULL;
        size_t digest_len = 0;
        int result;

        result = get_xattr_digest(dentry, xattr_name, &digest, &digest_len);
        if (result < 0) {
            status = INTEGRITY_NO_SIGNATURE;
            goto out;
        }

        result = verify_hmac(iint, xattr_value, xattr_value_len, digest, digest_len);
        if (result < 0)
            status = INTEGRITY_FAIL;

        kfree(digest);
    } else {
        status = INTEGRITY_NO_SIGNATURE;
    }

out:
    return status;
}
